  "Give a person a secret one-time code. They create their own login with it — the role and site are fixed by you.":
    "ବ୍ୟକ୍ତିଙ୍କୁ ଥରେ ଚାଲୁଥିବା ଗୁପ୍ତ କୋଡ୍ ଦିଅନ୍ତୁ। ସେ ତାହାରେ ନିଜ ଲଗଇନ୍ ତିଆରି କରିବେ — ଭୂମିକା ଓ ସାଇଟ୍ ଆପଣ ସ୍ଥିର କରନ୍ତି।",
