    "ଚାଲୁ: ଦଳ ଆପ୍ ବ୍ୟବହାର କଲା ଅନୁସାରେ ମଡ୍ୟୁଲ୍ ଗୋଟିଏ ଗୋଟିଏ ପାହାଚରେ ଖୋଲିବ (ପାହାଚ {level} / {total})।",
  "Off: every module switched on below is open now.": "ବନ୍ଦ: ତଳେ ଚାଲୁ ଥିବା ସବୁ ମଡ୍ୟୁଲ୍ ଏବେ ଖୋଲା।",
  "🔒 Opens at step {level}; switch on to open now":
    "🔒 ପାହାଚ {level} ରେ ଖୋଲିବ; ଏବେ ଖୋଲିବାକୁ ଚାଲୁ କରନ୍ତୁ",
  "Site and people": "ସାଇଟ୍ ଓ ଲୋକ",
  "Add your site and onboard labour, mistri, supervisor and driver.":
    "ଆପଣଙ୍କ ସାଇଟ୍ ଯୋଡ଼ନ୍ତୁ ଓ ଶ୍ରମିକ, ମିସ୍ତ୍ରୀ, ସୁପରଭାଇଜର ଓ ଡ୍ରାଇଭର ଯୋଡ଼ନ୍ତୁ।",
  "Add 3 workers": "3 ଜଣ ଶ୍ରମିକ ଯୋଡ଼ନ୍ତୁ",
  "Mark who came to work each day.": "ପ୍ରତିଦିନ କିଏ କାମକୁ ଆସିଲେ ଲେଖନ୍ତୁ।",
  "Mark attendance on 3 days": "3 ଦିନ ହାଜିରା ଦିଅନ୍ତୁ",
  "Daily reports and schedule": "ଦୈନିକ ରିପୋର୍ଟ ଓ ସିଡ୍ୟୁଲ୍",
  "Send the daily progress report and plan the work as tasks.":
    "ଦୈନିକ ପ୍ରଗତି ରିପୋର୍ଟ ପଠାନ୍ତୁ ଓ କାମକୁ ଟାସ୍କରେ ଯୋଜନା କରନ୍ତୁ।",
  "Send 3 daily progress reports": "3ଟି ଦୈନିକ ପ୍ରଗତି ରିପୋର୍ଟ ପଠାନ୍ତୁ",
  "Suppliers, bills, payments, petty cash, wages and advances.":
    "ଯୋଗାଣକାରୀ, ବିଲ୍, ଦେୟ, ଛୋଟ ନଗଦ, ମଜୁରି ଓ ଆଗୁଆ।",
  "Record a supplier bill, payment or petty cash entry": "ଯୋଗାଣକାରୀ ବିଲ୍, ଦେୟ ବା ଛୋଟ ନଗଦ ଲେଖନ୍ତୁ",
  "Ask for material from site and keep stock in the store.":
    "ସାଇଟରୁ ସାମଗ୍ରୀ ମାଗନ୍ତୁ ଓ ଷ୍ଟୋରରେ ଷ୍ଟକ୍ ରଖନ୍ତୁ।",
  "Send a material request": "ସାମଗ୍ରୀ ଅନୁରୋଧ ପଠାନ୍ତୁ",
  "Work orders, measurement book and RA bills for petty contractors.":
    "ଛୋଟ ଠିକାଦାରଙ୍କ ପାଇଁ ୱର୍କ ଅର୍ଡର, ମାପ ପୁସ୍ତିକା ଓ RA ବିଲ୍।",
  "Make a work order": "ୱର୍କ ଅର୍ଡର ତିଆରି କରନ୍ତୁ",
  "Documents and client billing": "ଦଲିଲ ଓ ଗ୍ରାହକ ବିଲିଂ",
  "Drawings, agreements and RA bills to the department.": "ଡ୍ରଇଂ, ଚୁକ୍ତି ଓ ବିଭାଗକୁ RA ବିଲ୍।",
