  "e.g. Install delivery main, chainage 0–250 m": "ଯେପରି ଡେଲିଭରି ମେନ୍ ବିଛାଇବା, ଚେନେଜ୍ 0–250 m",
  "e.g. Khurda Rural Water Supply": "ଯେପରି ଖୋର୍ଦ୍ଧା ଗ୍ରାମୀଣ ଜଳ ଯୋଗାଣ",
